class DataSink:
    def __init__(self, config: dict):
        self.config = config
        self.logger = get_logger('billing')

    def run(self, batch: list[dict]) -> dict:
        """Process one batch and return a summary."""
        results = [self.handle(item) for item in batch]
        return {'processed': len(results), 'failed': sum(r['failed'] for r in results)}

